bool validSettings(const Settings& s) {
  return s.magic==0x50455031&&memchr(s.ssid,0,sizeof(s.ssid))&&memchr(s.password,0,sizeof(s.password))&&
    memchr(s.name,0,sizeof(s.name))&&s.brightness>=10&&s.language<=2&&
    ((s.month==0&&s.day==0)||peppi::valid({2024,s.month,s.day}));
}
bool saveSettings(const Settings& s) {
  Preferences p;if(!validSettings(s)||!p.begin("peppi",false))return false;
  bool ok=p.putBytes("settings",&s,sizeof(s))==sizeof(s);p.end();return ok;
}
String randomHex() {
  char b[25];snprintf(b,sizeof(b),"%08lx%08lx%08lx",(unsigned long)esp_random(),(unsigned long)esp_random(),(unsigned long)esp_random());return String(b);
}
String json(const String& s) {
  String out="\"";
  for(size_t i=0;i<s.length();++i) {
    uint8_t c=s[i];if(c=='"'||c=='\\'){out+='\\';out+=char(c);}
    else if(c<32){char b[7];snprintf(b,sizeof(b),"\\u%04x",c);out+=b;}else out+=char(c);
  }
  return out+'"';
}
bool localDate(tm& t) {
  time_t now=time(nullptr);if(now<1704067200)return false;
  localtime_r(&now,&t);return peppi::valid({t.tm_year+1900,t.tm_mon+1,t.tm_mday});
}
