bool jpgOutput(int16_t x,int16_t y,uint16_t w,uint16_t h,uint16_t* pixels){
  if(!artworkPixels||!pixels||x<0||y<0||x+w>320||y+h>240)return false;
  for(uint16_t row=0;row<h;++row){
    memcpy(artworkPixels+uint32_t(y+row)*320+x,pixels+uint32_t(row)*w,uint32_t(w)*sizeof(uint16_t));
