    case countdown::Birthday:return tr("Geburtstag","Urodziny","Birthday");
    case countdown::Valentines:return tr("Valentinstag","Walentynki","Valentine's Day");
    case countdown::Easter:return tr("Ostern","Wielkanoc","Easter");
    case countdown::Vacation:return tr("Urlaub","Urlop","Vacation");
    case countdown::Halloween:return "Halloween";
    default:return tr("Weihnachten","Swieta","Christmas");
  }
