String musicCategory(){
  if(eventSettings.mode==countdown::Birthday)return "birthday";
  if(eventSettings.mode==countdown::Valentines)return "valentines";
  if(eventSettings.mode==countdown::Easter)return "easter";
  if(eventSettings.mode==countdown::Vacation)return "vacation";
  if(eventSettings.mode==countdown::Halloween)return "halloween";
  tm t{};if(!localDate(t))return "christmas";
  int m=t.tm_mon+1,d=t.tm_mday;
  if(m==12&&d==31)return "silvester";
  if(m==12&&d==5)return "krampus";
  if(m==12&&d==6)return "nikolaus";
  if((m==12&&d==27)||(m==1&&d==6))return "grincz";
  if(settings.month==m&&settings.day==d&&settings.month&&settings.day)return "birthday";
  return "christmas";
}
