bool safeMediaCategory(const String& c){
  static const char* allowed[]={"christmas","silvester","birthday","halloween","easter","valentines","vacation","krampus","nikolaus","grincz","normal"};
  for(const char* v:allowed)if(c==v)return true;return false;
}
String safeFileName(String s){
  s.replace("\\\\","_");s.replace("/","_");s.replace("..","_");
  String out;for(size_t i=0;i<s.length()&&out.length()<80;++i){char c=s[i];if((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='.'||c=='_'||c=='-'||c==' ')out+=c;}
  out.trim();return out;
}
