void drawArtwork(const String& name){
  if(!artworkPixels)return;
  for(size_t i=0;i<320UL*240UL;++i)artworkPixels[i]=BG;
  bool decoded=false;
  if(sdReady){
    String custom=customImageForArtwork(name);
    if(SD_MMC.exists(custom))decoded=TJpgDec.drawFsJpg(0,0,custom,SD_MMC)==JDR_OK;
  }
  if(!decoded){
    uint8_t* data=nullptr;size_t bytes=0;
    if(factoryassets::load(name,data,bytes)){
      decoded=TJpgDec.drawJpg(0,0,data,bytes)==JDR_OK;free(data);
    }
  }
  if(lvReady){
    artworkDescriptor.header.magic=LV_IMAGE_HEADER_MAGIC;
    artworkDescriptor.header.cf=LV_COLOR_FORMAT_RGB565;
    artworkDescriptor.header.w=320;artworkDescriptor.header.h=240;
    artworkDescriptor.header.stride=320*sizeof(uint16_t);
    artworkDescriptor.header.flags=0;
    artworkDescriptor.data_size=320UL*240UL*sizeof(uint16_t);
    artworkDescriptor.data=(const uint8_t*)artworkPixels;
    ui::setArtwork(&artworkDescriptor);
  }
  loadedArtwork=name;
}
