void advertisePortalDns(){
  auto* net=esp_netif_get_handle_from_ifkey("WIFI_AP_DEF");if(!net)return;
  esp_err_t stopped=esp_netif_dhcps_stop(net);
  if(stopped!=ESP_OK&&stopped!=ESP_ERR_ESP_NETIF_DHCP_ALREADY_STOPPED){Serial.println("DHCP stop failed");return;}
  esp_netif_dns_info_t info{};info.ip.type=ESP_IPADDR_TYPE_V4;info.ip.u_addr.ip4.addr=uint32_t(WiFi.softAPIP());
  esp_err_t dnsResult=esp_netif_set_dns_info(net,ESP_NETIF_DNS_MAIN,&info);
  dhcps_offer_t offer=OFFER_DNS;
  esp_err_t optionResult=esp_netif_dhcps_option(net,ESP_NETIF_OP_SET,ESP_NETIF_DOMAIN_NAME_SERVER,&offer,sizeof(offer));
  esp_err_t started=esp_netif_dhcps_start(net);
  Serial.printf("Portal DHCP/DNS: %d/%d/%d\n",dnsResult,optionResult,started);
}
void openAP() {
  if(!apActive){
    WiFi.softAPConfig(IPAddress(192,168,4,1),IPAddress(192,168,4,1),IPAddress(255,255,255,0));
    if(!WiFi.softAP(apName.c_str(),adminPassword.c_str())){Serial.println("AP failed");return;}
    advertisePortalDns();
    dns.setTTL(30);if(!dns.start(53,"*",WiFi.softAPIP()))Serial.println("Portal DNS bind failed");apActive=true;
  }
  configScreen=true;configOpened=millis();apActivity=millis();dirty=true;
}
