int guiSaveTime(const clocktime::Value& v){
  time_t epoch=0;if(v.zone>2 || (!v.internet&&!clocktime::toEpoch(v,epoch)))return 1;
  const uint8_t next=v.zone|(v.internet?4:0);Preferences p;
  if(!p.begin("peppi",false))return 2;
  bool saved=p.putUChar("clockMode",next)==1;p.end();if(!saved)return 2;
  if(!v.internet){esp_sntp_stop();timeval tv{};tv.tv_sec=epoch;if(settimeofday(&tv,nullptr)!=0){
    if(p.begin("peppi",false)){p.putUChar("clockMode",clockMode);p.end();}applyClockMode();return 2;
  }}
  clockMode=next;applyClockMode();guiBack();return 0;
}
