bool guiSaveBatteryVisible(bool visible){
  Preferences p;if(!p.begin("peppi",false))return false;
  bool ok=p.putBool("batteryVisible",visible)==1;p.end();
  if(ok){batteryVisible=visible;batteryMv=0;batteryPercent=-1;batterySampleAt=0;dirty=true;configOpened=millis();}
  return ok;
}
void batteryTick(){
  if(!batteryVisible||ota::busy())return;
  uint32_t now=millis();if(batterySampleAt&&uint32_t(now-batterySampleAt)<5000)return;
  batterySampleAt=now;
  static bool initialized=false;
  if(!initialized){pinMode(9,INPUT);analogSetPinAttenuation(9,ADC_11db);initialized=true;}
  unsigned sum=0;for(int i=0;i<16;++i)sum+=analogReadMilliVolts(9);
  unsigned mv=(sum+4)/8; // 200k/200k divider, 16 samples, multiply by two.
  batteryMv=batteryMv?(batteryMv*3+mv)/4:mv;
  int next=battery::percent(batteryMv);
  if(next!=batteryPercent){batteryPercent=next;dirty=true;}
}
