}

void lvFlush(lv_display_t* display,const lv_area_t* area,uint8_t* pixels){
  if(area&&pixels){
    uint16_t w=(uint16_t)(area->x2-area->x1+1),h=(uint16_t)(area->y2-area->y1+1);
    lcd.pushImage(area->x1,area->y1,w,h,(const uint16_t*)pixels);
  }
  lv_display_flush_ready(display);
}
void lvReadTouch(lv_indev_t*,lv_indev_data_t* data){
  touch::Point p;
  if(touch::raw(p)){data->state=LV_INDEV_STATE_PRESSED;data->point.x=p.x;data->point.y=p.y;}
  else data->state=LV_INDEV_STATE_RELEASED;
}
bool initLvgl(){
  if(!peppiuhr_prepare_lvgl_pool(LV_MEM_SIZE)){Serial.println("LVGL: PSRAM pool allocation failed");return false;}
  lv_init();
  artworkPixels=(uint16_t*)heap_caps_malloc(320UL*240UL*sizeof(uint16_t),MALLOC_CAP_SPIRAM|MALLOC_CAP_8BIT);
  lvDrawBuffer=(uint16_t*)heap_caps_malloc(320UL*24UL*sizeof(uint16_t),MALLOC_CAP_SPIRAM|MALLOC_CAP_8BIT);
  if(!artworkPixels||!lvDrawBuffer){Serial.println("LVGL: PSRAM allocation failed");return false;}
  lvDisplay=lv_display_create(320,240);
  if(!lvDisplay)return false;
  lv_display_set_color_format(lvDisplay,LV_COLOR_FORMAT_RGB565);
  lv_display_set_flush_cb(lvDisplay,lvFlush);
  lv_display_set_buffers(lvDisplay,lvDrawBuffer,nullptr,320UL*24UL*sizeof(uint16_t),LV_DISPLAY_RENDER_MODE_PARTIAL);
  lvTouch=lv_indev_create();
  if(!lvTouch)return false;
  lv_indev_set_type(lvTouch,LV_INDEV_TYPE_POINTER);
  lv_indev_set_read_cb(lvTouch,lvReadTouch);
  ui::Hooks hooks{guiOpenWifi,guiOpenPlayer,guiBack,guiPrevious,guiToggle,guiNext,guiSetVolume,guiSaveVolume,guiOpenTime,guiSaveTime,guiPreviewBrightness,guiSaveBrightness,guiSelectLanguage,guiOpenUpdate,guiSaveBatteryVisible};
  ui::init(hooks);
  lvReady=true;lvLastTick=millis();
  drawArtwork(currentArtwork());
  return true;
}
void updateClockModel(ui::Model& model){
  static String dynamicMain,dynamicSub;
  model.centerIntroOverDays=eventSettings.mode!=countdown::Christmas;
  tm t{};bool hasTime=localDate(t);
  if(eventSettings.mode!=countdown::Christmas){
    model.header=eventTitle();
    if(!countdown::configured(eventSettings)){
      model.mainText=tr("Datum einstellen","Ustaw date","Set event date");
      model.subText=tr("Im Web-Panel","W panelu WWW","In the web panel");
    }else if(!hasTime){
      model.timeUnset=true;
      model.mainText=tr("Bitte Zeit einstellen","Proszę ustawić czas","Please set the time");
      model.subText="";
    }else{
      auto result=countdown::calculate({t.tm_year+1900,t.tm_mon+1,t.tm_mday},eventSettings);
      if(result.today||result.started){
        model.mainText=result.started?tr("Urlaub","Urlop","Vacation"):eventTitle();
        if(result.started)model.subText=tr("hat begonnen!","rozpoczety!","has begun!");
        else {dynamicSub=screenName();model.subText=dynamicSub.c_str();}
      }else{
        dynamicMain=String(result.days);model.mainText=dynamicMain.c_str();
        const char* target=eventTitle();
        if(settings.language==1){switch(eventSettings.mode){case countdown::Birthday:target="urodzin";break;case countdown::Valentines:target="Walentynek";break;case countdown::Easter:target="Wielkanocy";break;case countdown::Vacation:target="urlopu";break;default:break;}}
        dynamicSub=String(result.days==1?tr("Tag bis ","dzień do ","day until "):tr("Tage bis ","dni do ","days until "))+target;
        model.subText=dynamicSub.c_str();
      }
    }
  }else{
    model.header=tr("Vorfreude","Odliczanie","Countdown");
    if(!hasTime){
      model.timeUnset=true;
      model.mainText=tr("Bitte Zeit einstellen","Proszę ustawić czas","Please set the time");
      model.subText="";
    }else{
      peppi::Date d{t.tm_year+1900,t.tm_mon+1,t.tm_mday};
      auto scene=peppi::scene(d);
      if(scene==peppi::Scene::Christmas){
        model.christmasGreeting=true;
        model.mainText=tr("Frohe\nWeihnachten","Wesołych\nŚwiąt","Merry\nChristmas");
        model.subText="";
      }else{
        static String daysText,untilText;
        daysText=String(peppi::daysToChristmas(d));
        untilText=peppi::christmasCountdownCaption(settings.language,peppi::daysToChristmas(d));
        model.mainText=daysText.c_str();model.subText=untilText.c_str();
      }
    }
  }
  static String status;
  if(hasTime){
    if(eventSettings.mode==countdown::Christmas&&peppi::birthday({t.tm_year+1900,t.tm_mon+1,t.tm_mday},eventSettings.birthMonth,eventSettings.birthDay))
      status=String(tr("Alles Gute, ","Sto lat, ","Happy birthday, "))+screenName();
    else {char b[40];snprintf(b,sizeof(b),"%02d.%02d.%04d   %02d:%02d",t.tm_mday,t.tm_mon+1,t.tm_year+1900,t.tm_hour,t.tm_min);status=b;}
  }else status=""; // The central setup message already explains this state.
  if(audioNotice&&music::state==music::Failed){
    status=music::error==music::NoCard?tr("SD-Karte einlegen","Wloz karte SD","Insert SD card"):music::error==music::MissingFile?tr("Musik fehlt","Brak muzyki","Music file missing"):tr("MP3 prüfen","Sprawdz MP3","Check MP3");
  }
  model.status=status.c_str();
}
void render(){
  if(otaScreen){otaui::tick();dirty=false;lastRender=millis();return;}
  if(!lvReady)return;
