void noCache(){server.sendHeader("Cache-Control","no-store");server.sendHeader("X-Content-Type-Options","nosniff");}
bool fromAP(){return apActive&&server.client().localIP()==WiFi.softAPIP();}
bool localHost() {
  String host=server.hostHeader();host.toLowerCase();
  if(host.endsWith(":80"))host.remove(host.length()-3);
  return (host=="weihnachtsuhr.local"||host=="peppi.local")||host==WiFi.localIP().toString()||host==WiFi.softAPIP().toString();
