void apiError(int code,const char* error){server.send(code,"application/json",String("{\"error\":")+json(error)+"}");}
bool loggedIn() {
  if(fromAP()){apActivity=millis();return true;}
  String cookies=server.header("Cookie"),token;
  while(cookies.length()) {
    int end=cookies.indexOf(';');String item=end<0?cookies:cookies.substring(0,end);item.trim();
    if(item.startsWith("peppi_session="))token=item.substring(14);
    if(end<0)break;cookies.remove(0,end+1);
  }
  for(const auto& s:sessions)if(s.token.length()&&token==s.token&&millis()-s.created<28800000UL)return true;
  return false;
}
bool authorize(bool mutation=false) {
  noCache();if(mutation&&ota::busy()){apiError(409,"ota_busy");return false;}if(!localHost()){apiError(403,"invalid_host");return false;}
  if(!loggedIn()){apiError(401,"auth_required");return false;}
  if(mutation&&server.header("X-Peppi-CSRF")!=csrf){apiError(403,"session_expired");return false;}return true;
}
