bool numberArg(const char* key,int lo,int hi,int& v) {
  String s=server.arg(key);if(!s.length()||s.length()>5)return false;
  for(size_t i=0;i<s.length();++i)if(s[i]<'0'||s[i]>'9')return false;v=s.toInt();return v>=lo&&v<=hi;
