const char* wifiConnectionState(){
  if(reconnect||wifiSettling)return "connecting";
  if(WiFi.status()==WL_CONNECTED)return "connected";
  if(wifiStartFailed)return "start_failed";
  if(wifiConnecting)return "connecting";
  unsigned reason=wifiDisconnectReason.load();
  if(reason==WIFI_REASON_AUTH_FAIL||reason==WIFI_REASON_4WAY_HANDSHAKE_TIMEOUT||reason==WIFI_REASON_HANDSHAKE_TIMEOUT)return "auth_failed";
  if(reason==WIFI_REASON_NO_AP_FOUND)return "not_found";
  if(wifiTimedOut)return "timeout";
  return "offline";
}
