    ",\"language\":"+json(peppi::languageCode(settings.language))+",\"apClient\":"+(fromAP()?"true":"false")+",\"apName\":"+json(apName)+",\"wallpaper\":"+json(wallpaper)+",\"art\":"+json(currentArtwork())+",\"music\":"+json(music::stateName())+",\"musicError\":"+json(music::errorName())+",\"musicCategory\":"+json(musicCategory())+",\"track\":"+json(music::title())+",\"volume\":"+String(music::volume.load())+",\"event\":"+json(countdown::code(eventSettings.mode))+",\"eventConfigured\":"+(result.configured?"true":"false")+",\"eventToday\":"+(valid&&result.today?"true":"false")+",\"eventStarted\":"+(valid&&result.started?"true":"false")+",\"targetDate\":"+json(target)+",\"vacationDate\":"+json(vacation)+"}";
