// Wi-Fi has an independent save action; unrelated form fields cannot block it.
void saveWifiForm() {
  if(!authorize(true))return;
  if(scanRunning||scanPending){apiError(409,"wifi_scan_busy");return;}
  if(server.args()>3||!server.hasArg("ssid")){bad("invalid_fields");return;}
  String ssid=server.arg("ssid"),pass=server.arg("password");
  if(!ssid.length()||ssid.length()>32||pass.length()>63){bad("invalid_fields");return;}
  Settings next=settings;
  if(server.arg("open")=="1")next.password[0]=0;
  else if(pass.length()){
    if(pass.length()<8){bad("invalid_password");return;}
    strlcpy(next.password,pass.c_str(),sizeof(next.password));
  }else if(ssid!=settings.ssid){bad("password_required");return;}
  strlcpy(next.ssid,ssid.c_str(),sizeof(next.ssid));
  bool changed=strcmp(next.ssid,settings.ssid)||strcmp(next.password,settings.password)||WiFi.status()!=WL_CONNECTED;
  if(!saveSettings(next)){apiError(500,"save_failed");return;}
  settings=next;dirty=true;
  server.send(200,"application/json",String("{\"ok\":true,\"reconnect\":")+(changed?"true":"false")+"}");
  if(changed){reconnect=true;reconnectPortal=true;reconnectAt=millis()+2500;}
}
void saveForm() {
  if(!authorize(true))return;if(server.args()>10){bad("invalid_fields");return;}
  Settings next=settings;String ssid=server.arg("ssid"),pass=server.arg("password"),name=server.hasArg("name")?server.arg("name"):String(settings.name);int month=settings.month,day=settings.day,brightness;
  int language=peppi::languageIndex(server.arg("language").c_str());
  if(language<0||ssid.length()>32||pass.length()>63||name.length()>48||(server.hasArg("month")&&!numberArg("month",0,12,month))||(server.hasArg("day")&&!numberArg("day",0,31,day))||!numberArg("brightness",10,255,brightness)){bad("invalid_fields");return;}
  if((month==0)!=(day==0)||(month&&!peppi::valid({2024,month,day}))){bad("invalid_date");return;}
  if(server.arg("open")=="1")next.password[0]=0;
  else if(pass.length()){if(pass.length()<8){bad("invalid_password");return;}strlcpy(next.password,pass.c_str(),sizeof(next.password));}
  else if(ssid!=settings.ssid&&ssid.length()){bad("password_required");return;}
  strlcpy(next.ssid,ssid.c_str(),sizeof(next.ssid));strlcpy(next.name,name.c_str(),sizeof(next.name));next.month=month;next.day=day;next.brightness=brightness;next.language=language;
  bool changed=strcmp(next.ssid,settings.ssid)||strcmp(next.password,settings.password)||WiFi.status()!=WL_CONNECTED;
  if(!saveSettings(next)){apiError(500,"save_failed");return;}
  settings=next;lcd.setBacklight(settings.brightness);dirty=true;
  server.send(200,"application/json",String("{\"ok\":true,\"reconnect\":")+(changed?"true":"false")+"}");
  if(changed){reconnect=true;reconnectPortal=true;reconnectAt=millis()+2500;}
}
void finishScanError(const char* reason){
  esp_wifi_scan_stop();WiFi.scanDelete();scanRunning=false;scanPending=false;
  scanFailed=true;scanHasResult=false;scanError=reason;scanFinished=millis();
  lastWifiAttempt=millis();WiFi.setAutoReconnect(false);Serial.printf("Scan failed: %s\n",reason);
}
void saveEvent(){
  if(!authorize(true))return;
  int mode=countdown::index(server.arg("event").c_str());if(mode<0){bad("invalid_event");return;}
  countdown::Config next=eventSettings;next.mode=mode;
  if(mode==countdown::Birthday){
    int month,day;String name=server.arg("name");
    if(name.length()>48||!numberArg("month",1,12,month)||!numberArg("day",1,31,day)){bad("invalid_date");return;}
    next.birthMonth=month;next.birthDay=day;strlcpy(next.name,name.c_str(),sizeof(next.name));
  }
  if(mode==countdown::Vacation){
    String date=server.arg("date");
    if(date.length()!=10||date[4]!='-'||date[7]!='-'){bad("invalid_date");return;}
    for(int i=0;i<10;++i)if(i!=4&&i!=7&&(date[i]<'0'||date[i]>'9')){bad("invalid_date");return;}
    next.vacYear=date.substring(0,4).toInt();next.vacMonth=date.substring(5,7).toInt();next.vacDay=date.substring(8,10).toInt();
  }
  if(!countdown::configured(next)){bad("invalid_date");return;}
  Preferences p;if(!p.begin("peppi",false)){apiError(500,"save_failed");return;}
  bool saved=p.putBytes("countdown",&next,sizeof(next))==sizeof(next);p.end();
  if(!saved){apiError(500,"save_failed");return;}eventSettings=next;forceFull=true;dirty=true;ok();
}
void scanTick() {
  if(!scanRunning)return;
  if(scanTiming::elapsed(millis(),scanStarted,scanTiming::TIMEOUT_MS)){finishScanError("scan_timeout");return;}
  if(scanPending){
    if(!scanTiming::elapsed(millis(),scanWaitAt,scanAttempts?scanTiming::RETRY_MS:scanTiming::SETTLE_MS))return;
    ++scanAttempts;int result=WiFi.scanNetworks(true,false,false,150);ScanGuard::extendTimeout();
    Serial.printf("Scan start attempt %u: %d\n",scanAttempts,result);
    if(result==WIFI_SCAN_RUNNING||result>=0){scanPending=false;return;}
    if(scanAttempts>=scanTiming::MAX_ATTEMPTS){finishScanError("scan_start_failed");return;}
    if(WiFi.status()!=WL_CONNECTED)WiFi.disconnect(false,false);
    scanWaitAt=millis();return;
  }
  int n=WiFi.scanComplete();
  if(n==WIFI_SCAN_RUNNING)return;
  if(n<0){finishScanError("scan_failed");return;}
  scanRunning=false;scanFinished=millis();scanFailed=false;scanHasResult=true;scanError="";scanResults="[";
  int order[40],count=0;
  for(int i=0;i<n&&i<40;++i)order[count++]=i;
  for(int i=0;i<count;++i)for(int j=i+1;j<count;++j)if(WiFi.RSSI(order[j])>WiFi.RSSI(order[i])){int v=order[i];order[i]=order[j];order[j]=v;}
  String names[20];int added=0;
  for(int k=0;k<count&&added<20;++k) {
    int i=order[k];String ssid=WiFi.SSID(i);if(!ssid.length())continue;
    bool duplicate=false;for(int j=0;j<added;++j)if(names[j]==ssid)duplicate=true;if(duplicate)continue;
    names[added++]=ssid;if(added>1)scanResults+=',';
    scanResults+="{\"ssid\":"+json(ssid)+",\"rssi\":"+String(WiFi.RSSI(i))+",\"secure\":"+(WiFi.encryptionType(i)==WIFI_AUTH_OPEN?"false":"true")+
      ",\"supported\":"+(WiFi.encryptionType(i)==WIFI_AUTH_WPA2_ENTERPRISE?"false":"true")+"}";
  }
  scanResults+=']';WiFi.scanDelete();WiFi.setAutoReconnect(false);lastWifiAttempt=millis();
  Serial.printf("Scan complete: %d networks, %d visible unique\n",n,added);
}

String mediaListJson(const String& category){
  if(!sdReady)return "{\"error\":\"audio_no_card\"}";
  if(!safeMediaCategory(category))return "{\"error\":\"invalid_event\"}";
  ensureMediaDirs(category);
  String out="{\"category\":"+json(category)+",\"customImage\":"+(SD_MMC.exists(mediaImagePath(category))?"true":"false")+",\"music\":[";
  File dir=SD_MMC.open(mediaMusicDir(category));bool first=true;
  if(dir&&dir.isDirectory()){
    for(File f=dir.openNextFile();f;f=dir.openNextFile()){
      if(f.isDirectory())continue;String n=f.name();if(!music::mediaFile(n))continue;
      if(!first)out+=",";first=false;
      String base=music::baseName(n);
      out+="{\"name\":"+json(base)+",\"size\":"+String((unsigned long)f.size())+"}";
    }
  }
  out+="]}";return out;
}
bool uploadAuthorized(){
  if(ota::busy())return false;
  if(!localHost()||!loggedIn())return false;
  return server.header("X-Peppi-CSRF")==csrf;
}
void handleMediaUpload(){
  HTTPUpload& up=server.upload();
  if(up.status==UPLOAD_FILE_START){
    mediaUploadOk=false;mediaUploadError="";mediaUploadBytes=0;
    if(!uploadAuthorized()){mediaUploadError="auth_required";return;}
    if(!sdReady){mediaUploadError="audio_no_card";return;}
    String kind=server.arg("kind"),category=server.arg("category");
    if(!safeMediaCategory(category)||(kind!="music"&&kind!="image")){mediaUploadError="invalid_fields";return;}
    ensureMediaDirs(category);
    String filename=safeFileName(up.filename);String lower=filename;lower.toLowerCase();
    String path;
    if(kind=="image"){
      if(!(lower.endsWith(".jpg")||lower.endsWith(".jpeg"))){mediaUploadError="image_jpeg_only";return;}
      path=mediaImagePath(category);
    }else{
      if(!music::mediaFile(filename)){mediaUploadError="audio_format";return;}
      if(!filename.length()){mediaUploadError="invalid_fields";return;}
      path=mediaMusicDir(category)+"/"+filename;
    }
    mediaUploadFile=SD_MMC.open(path,FILE_WRITE);
    if(!mediaUploadFile){mediaUploadError="write_failed";return;}
    mediaUploadOk=true;
  }else if(up.status==UPLOAD_FILE_WRITE){
    if(!mediaUploadOk||!mediaUploadFile)return;
    String kind=server.arg("kind");size_t limit=kind=="image"?MAX_IMAGE_UPLOAD:MAX_MUSIC_UPLOAD;
    if(mediaUploadBytes+up.currentSize>limit){mediaUploadError="file_too_large";mediaUploadOk=false;mediaUploadFile.close();return;}
    if(mediaUploadFile.write(up.buf,up.currentSize)!=up.currentSize){mediaUploadError="write_failed";mediaUploadOk=false;mediaUploadFile.close();return;}
    mediaUploadBytes+=up.currentSize;
  }else if(up.status==UPLOAD_FILE_END){
    if(mediaUploadFile)mediaUploadFile.close();
    if(mediaUploadOk&&server.arg("kind")=="image"){forceFull=true;dirty=true;}
  }else if(up.status==UPLOAD_FILE_ABORTED){
    if(mediaUploadFile)mediaUploadFile.close();mediaUploadOk=false;mediaUploadError="upload_aborted";
  }
}

