  server.sendHeader("X-Frame-Options","DENY");
  server.sendHeader("Content-Security-Policy","default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src data:; frame-ancestors 'none'");
  server.send_P(200,"text/html; charset=utf-8",CAPTIVE_PAGE);
}
