  server.on("/api/volume",HTTP_POST,[](){
    if(!authorize(true))return;int level;if(!numberArg("volume",0,100,level)){bad("invalid_volume");return;}
    Preferences p;if(!p.begin("peppi",false)){apiError(500,"save_failed");return;}
    bool saved=p.putUChar("volume",level)==1;p.end();if(!saved){apiError(500,"save_failed");return;}
    music::setVolume(level);ok();
  });
  server.on("/api/status",HTTP_GET,status);server.on("/api/settings",HTTP_POST,saveForm);server.on("/api/wifi",HTTP_POST,saveWifiForm);
  server.on("/api/scan",HTTP_POST,[](){
    if(!authorize(true))return;
    if(reconnect){apiError(409,"wifi_busy");return;}
    if(!scanRunning&&!scanTiming::useCache(scanFailed,scanHasResult,millis(),scanFinished)) {
      WiFi.scanDelete();WiFi.setAutoReconnect(false);
      if(WiFi.status()!=WL_CONNECTED)WiFi.disconnect(false,false);
      scanStarted=millis();scanWaitAt=scanStarted;lastWifiAttempt=scanStarted;
      scanFailed=false;scanError="";scanAttempts=0;scanPending=true;scanRunning=true;
    }
    ok();
  });
  server.on("/api/scan",HTTP_GET,[](){if(authorize())server.send(200,"application/json",String("{\"running\":")+(scanRunning?"true":"false")+",\"failed\":"+(scanFailed?"true":"false")+",\"reason\":"+json(scanError)+",\"attempts\":"+String(scanAttempts)+",\"networks\":"+scanResults+"}");});
  server.on("/api/time",HTTP_POST,[](){
    if(!authorize(true))return;String s=server.arg("epoch");if(s.length()!=10){bad("invalid_time");return;}
    for(size_t i=0;i<s.length();++i)if(s[i]<'0'||s[i]>'9'){bad("invalid_time");return;}
    int64_t seconds=strtoll(s.c_str(),nullptr,10),maxTime=sizeof(time_t)==4?2145916799LL:4102444799LL;
    if(seconds<1704067200LL||seconds>maxTime){bad("invalid_time");return;}
    timeval tv{};tv.tv_sec=time_t(seconds);if(settimeofday(&tv,nullptr)!=0){apiError(500,"invalid_time");return;}dirty=true;ok();
  });
  server.on("/api/sd",HTTP_POST,[](){if(authorize(true)){if(mountSD())ok();else apiError(409,"audio_busy");}});
  server.onNotFound([](){
    noCache();if(server.uri().startsWith("/api/")){server.send(404,"text/plain","Not found");return;}
    if(server.method()==HTTP_GET)portalProbe();else apiError(405,"method_not_allowed");
  });server.begin();
}
void wifiTick() {
  uint32_t now=millis();
  scanTick();
  if(reconnect&&int32_t(now-reconnectAt)>=0){
    reconnect=false;
    if(scanRunning){esp_wifi_scan_stop();WiFi.scanDelete();scanRunning=false;scanPending=false;scanHasResult=false;}
    if(reconnectPortal)openAP();reconnectPortal=false;WiFi.setAutoReconnect(false);
    // Arduino disconnect() returns early when connecting rather than connected.
    // Cancel the ESP-IDF attempt explicitly before changing credentials.
    esp_wifi_disconnect();
    wifiSettling=true;wifiSettleAt=now;wifiConnecting=false;
    wifiStartFailed=false;wifiTimedOut=false;offlineSince=now;onlineSince=0;
  }
  if(wifiSettling&&uint32_t(now-wifiSettleAt)>=500){
    wifiSettling=false;wifiDisconnectReason.store(0);lastWifiAttempt=now;
    if(settings.ssid[0]){
      bool started=WiFi.STA.begin()&&WiFi.STA.connect(settings.ssid,settings.password);
      wifiStartFailed=!started;
      wifiConnecting=!wifiStartFailed;wifiConnectAt=now;
    }
    dirty=true;
  }
  if(wifiConnecting&&WiFi.status()!=WL_CONNECTED&&uint32_t(now-wifiConnectAt)>=30000){
    wifiConnecting=false;wifiTimedOut=true;dirty=true;
  }
  if(WiFi.status()==WL_CONNECTED){
    wifiConnecting=false;wifiTimedOut=false;wifiStartFailed=false;
    if(!onlineSince){onlineSince=now;dirty=true;Serial.print("Panel IP: ");Serial.println(WiFi.localIP());}offlineSince=0;
    if(!mdnsReady){mdnsReady=MDNS.begin("weihnachtsuhr");if(mdnsReady)MDNS.addService("http","tcp",80);}
    if(apActive&&!configScreen&&WiFi.softAPgetStationNum()==0&&now-apActivity>600000){dns.stop();WiFi.softAPdisconnect(true);apActive=false;}
  }else{
    if(onlineSince){onlineSince=0;dirty=true;}if(!offlineSince)offlineSince=now;
    if(!apActive&&now-offlineSince>30000)openAP();
    if(!scanRunning&&!scanPending&&!reconnect&&!wifiSettling&&!wifiConnecting&&settings.ssid[0]&&now-lastWifiAttempt>60000){reconnect=true;reconnectAt=now;}
  }
  if(configScreen&&!timeScreen&&!otaScreen&&now-configOpened>180000){configScreen=false;dirty=true;}
}
void pollBoot() {
  uint32_t now=millis();if(digitalRead(0)==LOW){if(!bootSince)bootSince=now;if(!bootConsumed&&now-bootSince>3000){bootConsumed=true;openAP();}}
  else{bootSince=0;bootConsumed=false;}
}
}
void setup() {
  Serial.begin(115200);pinMode(0,INPUT_PULLUP);
  music::quietIdle(); // Keep the ES3C28P amplifier muted during boot.
  Preferences p;if(p.begin("peppi",false)){
    if(p.getBytesLength("settings")==sizeof(settings))p.getBytes("settings",&settings,sizeof(settings));if(!validSettings(settings))settings=Settings{};
    adminPassword=p.getString("admin","");if(adminPassword.length()!=12){adminPassword=randomHex().substring(0,12);ready=p.putString("admin",adminPassword)==adminPassword.length();}else ready=true;
    wallpaper=p.getString("wallpaper","normal");if(!validWallpaper(wallpaper))wallpaper="normal";
    eventSettings.birthMonth=settings.month;eventSettings.birthDay=settings.day;strlcpy(eventSettings.name,settings.name,sizeof(eventSettings.name));
    countdown::Config loaded;
    if(p.getBytesLength("countdown")==sizeof(loaded)&&p.getBytes("countdown",&loaded,sizeof(loaded))==sizeof(loaded)&&countdown::validConfig(loaded))eventSettings=loaded;
    batteryVisible=p.getBool("batteryVisible",false);
    music::volume=p.getUChar("volume",50);if(music::volume>100)music::volume=50;
    clockMode=p.getUChar("clockMode",4);if(clockMode>6||(clockMode&3)>2)clockMode=4;
    p.end();
  }
  lcd.init();lcd.setRotation(1);TJpgDec.setCallback(jpgOutput);TJpgDec.setJpgScale(1);TJpgDec.setSwapBytes(false);lcd.fillScreen(BG);lcd.setBacklight(settings.brightness);
  factoryassets::begin();
  touch::begin();music::begin();mountSD();
  if(!ready){center(tr("Speicherfehler","Blad pamieci","Storage error"),160,70,4,GOLD);center(tr("Bitte neu starten","Uruchom ponownie","Please restart"),160,110,2);return;}
  if(!initLvgl()){center(tr("LVGL Speicherfehler","Blad pamieci LVGL","LVGL memory error"),160,70,4,GOLD);return;}
  char suffix[7];snprintf(suffix,sizeof(suffix),"%06lx",(unsigned long)(ESP.getEfuseMac()&0xFFFFFF));apName=String("Weihnachtsuhr-")+suffix;
  WiFi.persistent(false);WiFi.setHostname("weihnachtsuhr");WiFi.mode(WIFI_AP_STA);WiFi.setAutoReconnect(false);
  WiFi.onEvent([](WiFiEvent_t event,WiFiEventInfo_t info){if(event==ARDUINO_EVENT_WIFI_STA_DISCONNECTED)wifiDisconnectReason.store(info.wifi_sta_disconnected.reason);else if(event==ARDUINO_EVENT_WIFI_STA_GOT_IP)wifiDisconnectReason.store(0);});csrf=randomHex();
  applyClockMode();routes();
  if(settings.ssid[0]){reconnect=true;reconnectAt=millis();}else openAP();
  Serial.println("Weihnachtsuhr ES3C28P LVGL 9.5. Hold BOOT for 3s after startup to open setup.");render();
}
void loop() {
  if(!ready||!lvReady){ota::bootFailed();delay(50);return;}
  uint32_t now=millis();lv_tick_inc(now-lvLastTick);lvLastTick=now;
  batteryTick();
  server.handleClient();if(apActive)dns.processNextRequest();if(!ota::busy()){wifiTick();pollBoot();music::setCategory(musicCategory());music::loop(sdReady);}
  static int lastMusic=-1;int ms=music::state.load();if(ms!=lastMusic){lastMusic=ms;audioNotice=ms==music::Failed;audioNoticeAt=millis();dirty=true;}
  static String lastTrack;String nowTrack=music::title();if(nowTrack!=lastTrack){lastTrack=nowTrack;dirty=true;}
  if(audioNotice&&uint32_t(millis()-audioNoticeAt)>=4000){audioNotice=false;dirty=true;}
  tm t{};static int lastMinute=-1;if(localDate(t)&&t.tm_min!=lastMinute){lastMinute=t.tm_min;dirty=true;}
  if(ota::busy()&&!otaScreen)guiOpenUpdate();
  if(dirty&&millis()-lastRender>100)render();
  static uint32_t otaTick=0;if(now-otaTick>250){otaTick=now;otaui::tick();}
  lv_timer_handler();ota::bootHealthy();delay(2);
}

