void syncLettering() {
  for(auto& group:lettering) {
    auto* o=group.label;if(!o)continue;
    lv_obj_set_style_text_color(o,lv_color_hex(festiveText?0xFFDA79:clockInk),0);
    for(int i=0;i<5;++i) {
      auto* shade=group.layers[i];
      if(lv_obj_has_flag(o,LV_OBJ_FLAG_HIDDEN))lv_obj_add_flag(shade,LV_OBJ_FLAG_HIDDEN);
      else lv_obj_remove_flag(shade,LV_OBJ_FLAG_HIDDEN);
