void show(Screen s) {
  current = s;
  if(s!=Screen::Wifi)lv_obj_add_flag(batteryOverlay,LV_OBJ_FLAG_HIDDEN);
  if(s!=Screen::Wifi)lv_obj_add_flag(languageOverlay,LV_OBJ_FLAG_HIDDEN);
  if(s==Screen::Clock) lv_screen_load(clockPage);
  else if(s==Screen::Wifi) lv_screen_load(wifiPage);
  else if(s==Screen::Time) showTimeEditor();
  else lv_screen_load(playerPage);
}

void update(const Model& m) {
  const unsigned lang = m.language <= 2 ? m.language : 0;
  activeLanguage=lang;
  batteryShown=m.batteryVisible;
  lv_label_set_text(batteryHeading,lang==1?"Bateria":lang==2?"Battery":"Batterie");
  lv_label_set_text(batteryDescription,lang==1?"Pokaż stan baterii\nPoziom szacowany z napięcia":lang==2?"Show battery status\nLevel estimated from voltage":"Batteriestand anzeigen\nAus Spannung geschätzt");
  if(m.batteryVisible)lv_obj_add_state(batterySwitch,LV_STATE_CHECKED);else lv_obj_remove_state(batterySwitch,LV_STATE_CHECKED);
  if(m.batteryVisible){
    lv_obj_remove_flag(batteryBadge,LV_OBJ_FLAG_HIDDEN);
    if(m.batteryPercent>=0){
      lv_label_set_text_fmt(batteryValue,"%d%%",m.batteryPercent);
      lv_obj_set_width(batteryFill,1+14*m.batteryPercent/100);
      lv_obj_set_style_bg_color(batteryFill,m.batteryPercent<=15?lv_color_hex(0xFF725E):GOLD,0);
      lv_obj_remove_flag(batteryFill,LV_OBJ_FLAG_HIDDEN);
    }else{lv_label_set_text(batteryValue,"--");lv_obj_add_flag(batteryFill,LV_OBJ_FLAG_HIDDEN);}
  }else lv_obj_add_flag(batteryBadge,LV_OBJ_FLAG_HIDDEN);

  lv_label_set_text(languageHeading,lang==1?"Język":lang==2?"Language":"Sprache");
  for(unsigned i=0;i<3;++i){
    lv_obj_set_style_bg_color(languageButtons[i],i==lang?GOLD:PANEL,0);
    lv_obj_set_style_text_color(lv_obj_get_child(languageButtons[i],0),i==lang?INK:CREAM,0);
  }
  if(!lv_obj_has_state(brightnessSlider,LV_STATE_PRESSED)){
    lv_slider_set_value(brightnessSlider,m.brightness<10?10:m.brightness,LV_ANIM_OFF);
    lv_label_set_text_fmt(brightnessValue,"%u%%",unsigned((lv_slider_get_value(brightnessSlider)*100+127)/255));
  }
  if(clockMain) {
    const char* value=m.mainText?m.mainText:"";
    bool numeric=*value!='\0';for(const char* p=value;*p;++p)if(*p<'0'||*p>'9')numeric=false;
    const char* subtitle=m.subText?m.subText:"";
    std::string unit;
    if(numeric) {
      const char* space=strchr(subtitle,' ');
      if(space){unit.assign(subtitle,space-subtitle);subtitle=space+1;}
    }
    lv_label_set_text(clockMain,value);lv_label_set_text(clockSub,subtitle);
    lv_label_set_long_mode(clockMain,LV_LABEL_LONG_DOT);
    lv_label_set_text(clockIntro,lang==1?"Jeszcze":lang==2?"Only":"Noch");
    lv_label_set_text(clockUnit,unit.c_str());
    auto place=[](lv_obj_t* o,int x,int y,int w){lv_obj_set_width(o,w);lv_obj_set_align(o,LV_ALIGN_TOP_LEFT);lv_obj_set_pos(o,x,y);};
    if(numeric) {
      lv_obj_remove_flag(clockIntro,LV_OBJ_FLAG_HIDDEN);lv_obj_remove_flag(clockUnit,LV_OBJ_FLAG_HIDDEN);
      lv_obj_set_style_text_font(clockMain,&story_digits,0);
      lv_obj_set_style_text_font(clockIntro,&story_text,0);
      lv_obj_set_style_text_font(clockUnit,&story_text,0);
      lv_point_t digits,word;
      lv_text_get_size(&digits,value,&story_digits,0,0,LV_COORD_MAX,LV_TEXT_FLAG_NONE);
      lv_text_get_size(&word,unit.c_str(),&story_text,0,0,LV_COORD_MAX,LV_TEXT_FLAG_NONE);
      const int total=digits.x+word.x+6;
      place(clockMain,clockCenter-total/2,45+clockShift,digits.x+2);
      place(clockUnit,clockCenter-total/2+digits.x+6,88+clockShift,word.x+2);
      if(strlen(value)==2&&lang==0){place(clockMain,clockCenter-84,45+clockShift,110);place(clockUnit,clockCenter-3,86+clockShift,70);}
      place(clockIntro,m.centerIntroOverDays ? lv_obj_get_x(clockMain)+(lv_obj_get_width(clockMain)-110)/2 : (clockCenter==160?29:102),33+clockShift,m.centerIntroOverDays?110:90);
      place(clockSub,clockCenter==160?32:80,117+clockShift,clockCenter==160?256:232);
    } else {
      lv_obj_add_flag(clockIntro,LV_OBJ_FLAG_HIDDEN);lv_obj_add_flag(clockUnit,LV_OBJ_FLAG_HIDDEN);
      place(clockMain,clockCenter==160?32:80,75+clockShift,clockCenter==160?256:232);
      place(clockSub,clockCenter==160?32:80,120+clockShift,clockCenter==160?256:232);
      lv_obj_set_style_text_font(clockMain,&story_text,0);
    }
    lv_obj_set_style_text_font(clockSub,&story_text,0);
    lv_label_set_long_mode(clockSub,LV_LABEL_LONG_DOT);
    // Christmas typography: larger digits, larger words and intro just left of the digits.
    // Preserve the narrower composition used for character artwork.
    if(numeric&&!m.centerIntroOverDays&&!compactClock&&clockCenter==160) {
      const lv_font_t* digitsFont=&story_digits_88;
      const lv_font_t* wordsFont=&story_text_32;
      lv_point_t digits,word,intro;
      lv_text_get_size(&digits,value,digitsFont,0,0,LV_COORD_MAX,LV_TEXT_FLAG_NONE);
      lv_text_get_size(&word,unit.c_str(),wordsFont,0,0,LV_COORD_MAX,LV_TEXT_FLAG_NONE);
      if(digits.x+word.x+6>250){digitsFont=&story_digits;lv_text_get_size(&digits,value,digitsFont,0,0,LV_COORD_MAX,LV_TEXT_FLAG_NONE);}
      lv_obj_set_style_text_font(clockMain,digitsFont,0);
      for(auto* o:{clockIntro,clockUnit,clockSub})lv_obj_set_style_text_font(o,wordsFont,0);
      const int numberX=clockCenter-(digits.x+word.x+6)/2;
      const int numberY=43+clockShift;
      place(clockMain,numberX,numberY,digits.x+2);
      place(clockUnit,numberX+digits.x+6,numberY+digitsFont->line_height-digitsFont->base_line-wordsFont->line_height+wordsFont->base_line,word.x+2);
      lv_text_get_size(&intro,lv_label_get_text(clockIntro),wordsFont,0,0,LV_COORD_MAX,LV_TEXT_FLAG_NONE);
      // Balance the visible gap above the digits with the caption below them.
      place(clockIntro,numberX+(digits.x-intro.x)/2-5,7+clockShift,intro.x+4);
      place(clockSub,24,102+clockShift,272);
    }
    if(compactClock&&numeric) {
      lv_obj_set_style_text_font(clockMain,&story_digits_52,0);
      lv_obj_set_style_text_font(clockIntro,&story_text_20,0);
      lv_obj_set_style_text_font(clockUnit,&story_text_20,0);
      lv_obj_set_style_text_font(clockSub,&story_text_20,0);
      place(clockIntro,222,30,90);place(clockMain,211,57,102);
      place(clockUnit,232,109,80);
      place(clockSub,200,137,116);
      lv_point_t numberSize;
      lv_text_get_size(&numberSize,value,&story_digits_52,0,0,LV_COORD_MAX,LV_TEXT_FLAG_NONE);
      if(numberSize.x>98)lv_obj_set_style_text_font(clockMain,&story_digits_36,0);
      lv_label_set_long_mode(clockSub,LV_LABEL_LONG_WRAP);
    }
    lv_obj_update_layout(clockPage);
    for(auto* o:{clockMain,clockSub}) {
      if(compactClock&&numeric&&o==clockSub)continue;
      lv_point_t size;lv_text_get_size(&size,lv_label_get_text(o),lv_obj_get_style_text_font(o,LV_PART_MAIN),0,0,LV_COORD_MAX,LV_TEXT_FLAG_NONE);
      if(!numeric||o==clockSub) {
        if(size.x>lv_obj_get_width(o)-4)lv_obj_set_style_text_font(o,&ui_font_20,0);
        lv_text_get_size(&size,lv_label_get_text(o),lv_obj_get_style_text_font(o,LV_PART_MAIN),0,0,LV_COORD_MAX,LV_TEXT_FLAG_NONE);
        if(size.x>lv_obj_get_width(o)-4)lv_obj_set_style_text_font(o,&ui_font_16,0);
      }
    }
    if(m.timeUnset) {
      lv_obj_set_style_text_font(clockMain,&story_text_32,0);
      place(clockMain,18,85,284);
      lv_label_set_text(clockSub,"");
    }
    if(m.christmasGreeting) {
      lv_obj_set_style_text_font(clockMain,&story_text_44,0);
      lv_label_set_long_mode(clockMain,LV_LABEL_LONG_WRAP);
      lv_obj_set_style_text_line_space(clockMain,-5,0);
      place(clockMain,55,30,250);
      lv_label_set_text(clockSub,"");
    } else lv_obj_set_style_text_line_space(clockMain,0,0);
    festiveText=m.christmasGreeting;
    lv_obj_update_layout(clockPage);syncLettering();
  }
  if(clockStatus) {
    lv_label_set_text(clockStatus, m.status ? m.status : "");
    if(m.status && *m.status) lv_obj_remove_flag(clockStatus, LV_OBJ_FLAG_HIDDEN);
    else lv_obj_add_flag(clockStatus, LV_OBJ_FLAG_HIDDEN);
  }
  if(wifiStatus) lv_label_set_text(wifiStatus, m.wifi ? m.wifi : "WLAN nicht verbunden");
  if(wifiName) lv_label_set_text(wifiName, m.apName ? m.apName : "");
  if(wifiPassword) lv_label_set_text(wifiPassword, m.password ? m.password : "");
  const char* track = m.track ? m.track : "No track selected";
  if(trackLabel && strcmp(lv_label_get_text(trackLabel), track)) lv_label_set_text(trackLabel, track);
  if(playerStatus) {
    lv_label_set_text(playerStatus, m.playerState ? m.playerState : "");
    if(m.playerState && *m.playerState) lv_obj_remove_flag(playerStatus, LV_OBJ_FLAG_HIDDEN);
    else lv_obj_add_flag(playerStatus, LV_OBJ_FLAG_HIDDEN);
  }
  if(sdLabel) lv_label_set_text(sdLabel, m.storageStatus ? m.storageStatus : "SD card");
  if(volumeSlider && !lv_obj_has_state(volumeSlider, LV_STATE_PRESSED)) lv_slider_set_value(volumeSlider, m.volume, LV_ANIM_OFF);
  lv_obj_t* playLabel = lv_obj_get_child(playButton, 0);
  if(playLabel) lv_label_set_text(playLabel, m.playing ? LV_SYMBOL_PAUSE : LV_SYMBOL_PLAY);
  if(volumeValue) lv_label_set_text_fmt(volumeValue, "%u%%", unsigned(lv_slider_get_value(volumeSlider)));
}

void setWifiArtwork(const char* name) {
  int x = 116, y = 66, width = 154;
  if(name && !strcmp(name, "wifi_vacation")) { x = 134; y = 57; width = 138; }
  else if(name && !strcmp(name, "wifi_valentines")) { x = 126; y = 66; width = 145; }
  else if(name && !strcmp(name, "wifi_silvester")) { x = 127; y = 61; width = 145; }
  else if(name && !strcmp(name, "wifi_birthday")) { x = 125; y = 62; width = 150; }
  else if(name && !strcmp(name, "wifi_easter")) { x = 115; y = 66; width = 158; }
  else if(name && !strcmp(name, "wifi_halloween")) { x = 124; y = 62; width = 155; }
  const bool decemberBoard=name && (!strcmp(name,"wifi_krampus")||!strcmp(name,"wifi_nikolaus"));
  if(decemberBoard){x=112;y=82;width=158;}
  lv_obj_t* labels[] = {wifiTitle, wifiName, wifiPassword, wifiIp};
  const int offsets[] = {0, decemberBoard?20:23, decemberBoard?54:63, decemberBoard?72:83};
  for(unsigned i = 0; i < 4; ++i) {
    lv_obj_set_width(labels[i], width);
    lv_obj_set_pos(labels[i], x, y + offsets[i]);
  }
}

void setClockArtwork(const char* name) {
  compactClock=false;clockCenter=160;clockShift=0;clockInk=0xFFE0A0;clockOutline=0x352148;
  if(!name)return;
  if(!strcmp(name,"birthday_generic")||!strcmp(name,"valentines")) {clockInk=0x71264C;clockOutline=0xFFF0D8;}
  else if(!strcmp(name,"easter")){clockInk=0x255739;clockOutline=0xFFF3D2;}
  else if(!strcmp(name,"vacation")){clockInk=0x143F59;clockOutline=0xFFF0CD;clockShift=-8;}
  else if(!strcmp(name,"halloween")){clockInk=0xFFCF81;clockOutline=0x23152F;clockShift=-8;}
  else if(!strcmp(name,"krampus")||!strcmp(name,"nikolaus")||!strcmp(name,"grincz")){clockShift=-8;clockCenter=196;}
  else if(!strcmp(name,"normal_alt"))clockShift=-8;
  else if(!strcmp(name,"grincz_alt")){compactClock=true;clockInk=0x142C46;clockOutline=0xFFF0D8;}
  else if(!strcmp(name,"board")){clockInk=0x442B20;clockOutline=0xF5DAB3;}
  else if(!strcmp(name,"birthday"))clockShift=38;
}
void setArtwork(const lv_image_dsc_t* image) {
  // The RGB565 buffer is reused across themes: invalidate cached decoded/draw data.
  lv_image_cache_drop(image);
  lv_image_header_cache_drop(image);
  if(clockArt) lv_image_set_src(clockArt, image);
  if(wifiArt) lv_image_set_src(wifiArt, image);
  if(playerArt) lv_image_set_src(playerArt, image);
  setTimeArtwork(image);
}
}

