#pragma once
#include "Countdown.h"
namespace artworkselection {
inline const char* clock(uint8_t mode, peppi::Date date, const char* wallpaper,
                         int birthMonth=0,int birthDay=0) {
  switch(mode) {
    case countdown::Birthday:return "birthday_generic";
    case countdown::Valentines:return "valentines";
    case countdown::Easter:return "easter";
    case countdown::Vacation:return "vacation";
    case countdown::Halloween:return "halloween";
  }
  if(!peppi::valid(date))return "normal";
  // Christmas mode: holiday art takes precedence over wallpaper and birthday overlay.
  if(peppi::scene(date)==peppi::Scene::Christmas)return "christmas";
  if(peppi::scene(date)==peppi::Scene::Krampus)return "krampus";
  if(peppi::scene(date)==peppi::Scene::Nikolaus)return "nikolaus";
  if(date.month==10&&date.day==31)return "halloween";
  if(date.month==birthMonth&&date.day==birthDay)return "birthday";
  if(date.month==12&&date.day==27)return "grincz";
  if(date.month==1&&date.day==6)return "grincz_alt";
  if(date.month==12&&date.day==31)return "silvester";
  return wallpaper;
}
}

