namespace ota {
constexpr char VERSION[]="1.19.11";
constexpr char TARGET[]="es3c28p-esp32s3-16mb";
inline bool versionParts(const char* s,uint32_t out[3]) {
 if(!s)return false;
 for(int i=0;i<3;++i){if(*s<'0'||*s>'9')return false;uint32_t n=0;int digits=0;
  while(*s>='0'&&*s<='9'){if(++digits>5)return false;n=n*10+(*s++-'0');if(n>65535)return false;}out[i]=n;
  if(i<2){if(*s++!='.')return false;}else if(*s)return false;
 }return true;
}
inline bool newer(const char* candidate,const char* current=VERSION){uint32_t a[3],b[3];if(!versionParts(candidate,a)||!versionParts(current,b))return false;for(int i=0;i<3;++i)if(a[i]!=b[i])return a[i]>b[i];return false;}
inline bool validHash(const char* s){if(!s||strlen(s)!=64)return false;for(int i=0;i<64;++i)if(!((s[i]>='0'&&s[i]<='9')||(s[i]>='a'&&s[i]<='f')))return false;return true;}
inline bool allowedUrl(const char* url){
 if(!url)return false;
 constexpr char repo[]="https://github.com/voltex-at/Peppiuhr/releases/";
 constexpr char assets[]="https://release-assets.githubusercontent.com/";
 return strncmp(url,repo,sizeof(repo)-1)==0||strncmp(url,assets,sizeof(assets)-1)==0;
}
}

