"""Produce versioned, small SOURCE_BIN release and OTA manifest from actual build."""
import hashlib,json,re,zipfile,shutil
from pathlib import Path
root=Path(__file__).resolve().parents[1]
version=re.search(r'VERSION\[\]="([0-9.]+)"',(root/'src/OtaPolicy.h').read_text())[1]
target=re.search(r'TARGET\[\]="([^"]+)"',(root/'src/OtaPolicy.h').read_text())[1]
build=root/'.pio/build/es3c28p';out=root/'dist';out.mkdir(exist_ok=True)
for name in ['firmware.bin','firmware-merged.bin','flash-manifest.json']:shutil.copy2(build/name,out/name)
raw=(out/'firmware.bin').read_bytes()
assert raw[0]==0xe9 and int.from_bytes(raw[12:14],'little')==9
assert 256<=len(raw)<=7340032
manifest={'schema':1,'version':version,'target':target,'size':len(raw),'sha256':hashlib.sha256(raw).hexdigest(),'url':f'https://github.com/voltex-at/Peppiuhr/releases/download/v{version}/firmware.bin','notes':{'de':'Batterie-Symbol in den Einstellungen und optionaler geschätzter Batteriestand.','pl':'Ikona baterii w ustawieniach i opcjonalny szacowany poziom naładowania.','en':'Battery settings icon and optional estimated battery level.'}}
(out/'ota.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
with zipfile.ZipFile(out/f'Peppiuhr-v{version}-SOURCE_BIN.zip','w',zipfile.ZIP_DEFLATED,compresslevel=9) as z:
 for d in ['src','include','licenses','tools','tests','.github','docs']:
  for p in sorted((root/d).rglob('*')):
   if p.is_file() and '__pycache__' not in p.parts and p.name not in ['web_preview.cjs','render_preview.py','ui_preview.cpp','restyle_portal.py']:z.write(p,'source/'+str(p.relative_to(root)))
 for n in ['platformio.ini','partitions_16MB.csv','README.md','.gitignore']:z.write(root/n,'source/'+n)
 for n in ['firmware.bin','firmware-merged.bin','flash-manifest.json','ota.json']:z.write(out/n,'bin/'+n)
 z.write(root/f'docs/CHANGELOG-v{version}.md','CHANGES_AND_INSTALL.md')
print(json.dumps(manifest,indent=2,ensure_ascii=False))

