#include <cassert>
#include <iostream>
#include "Countdown.h"
#include "ArtworkSelection.h"
#include <cstring>
int main() {
  assert(peppi::valid({2024,2,29}));
  assert(!peppi::valid({2025,2,29}));
  assert(!peppi::valid({2026,13,1}));
  assert(peppi::daysToChristmas({2026,12,23}) == 1);
  assert(peppi::daysToChristmas({2026,1,6}) == 352);
  for (int day=24; day<=26; ++day) assert(peppi::daysToChristmas({2026,12,day}) == 0);
  assert(peppi::daysToChristmas({2026,12,27}) == 362);
  for(int y=2024;y<=2099;++y)for(int day=24;day<=26;++day) {
    assert(!strcmp(artworkselection::clock(countdown::Christmas,{y,12,day},"halloween",12,day),"christmas"));
    assert(peppi::daysToChristmas({y,12,day})==0);
  }
  assert(!strcmp(artworkselection::clock(countdown::Halloween,{2026,10,31},"normal"),"halloween"));
  for(int y=2024;y<=2099;++y){
    assert(!strcmp(artworkselection::clock(countdown::Christmas,{y,12,5},"normal",12,5),"krampus"));
    assert(!strcmp(artworkselection::clock(countdown::Christmas,{y,12,6},"normal",12,6),"nikolaus"));
    assert(peppi::daysToChristmas({y,12,5})==19);
    assert(peppi::daysToChristmas({y,12,6})==18);
  }
  assert(!strcmp(artworkselection::clock(countdown::Christmas,{2026,10,31},"normal"),"halloween"));
  assert(!strcmp(artworkselection::clock(countdown::Christmas,{2026,10,30},"normal"),"normal"));
  assert(!strcmp(artworkselection::clock(countdown::Christmas,{2026,11,1},"normal"),"normal"));
  assert(peppi::daysToChristmas({2026,10,31})==54);
  countdown::Config cfg;
  cfg.mode=countdown::Birthday; cfg.birthMonth=2; cfg.birthDay=29;
  auto r=countdown::calculate({2025,3,1},cfg);
  assert(r.configured && r.target.year==2028 && r.target.month==2 && r.target.day==29 && r.days==1095);
  cfg.mode=countdown::Vacation; cfg.vacYear=2026; cfg.vacMonth=7; cfg.vacDay=1;
  r=countdown::calculate({2026,7,2},cfg);
  assert(r.started && r.days==0);
  cfg.mode=countdown::Easter;
  r=countdown::calculate({2026,4,4},cfg);
  assert(r.days==1 && r.target.month==4 && r.target.day==5);
  cfg.mode=countdown::Halloween;
  r=countdown::calculate({2026,10,31},cfg); assert(r.today && r.days==0);
  cfg.mode=countdown::Valentines;
  r=countdown::calculate({2026,2,15},cfg); assert(r.target.year==2027 && r.days==364);
  std::cout << "Calendar boundary tests: PASS\n";
}

