#pragma once
// Approximate single-cell Li-ion state of charge, not a charging detector.
namespace battery {
inline int percent(unsigned mv) {
  if(mv<2500 || mv>4350)return -1;
  const unsigned volts[]={3300,3500,3600,3700,3750,3800,3850,3900,4000,4100,4200};
  const int levels[]={0,5,10,20,30,40,50,60,75,90,100};
  if(mv<=volts[0])return 0;
  for(unsigned i=1;i<11;++i)if(mv<=volts[i])return levels[i-1]+int((mv-volts[i-1])*(levels[i]-levels[i-1])/(volts[i]-volts[i-1]));
  return 100;
}
}
